from langflow.custom import Component
from langflow.io import MessageInput, Output
from langflow.schema import Data
from langflow.schema.message import Message
import pandas as pd
import numpy as np
import re
import json

class DataProfilingComponent(Component):
    display_name = "CSV Data Profiling"
    description = "接收 Chat Input 的 Message，提取 CSV 路径并进行数据探查"

    inputs = [
        MessageInput(
            name="input_message",
            display_name="Chat Input Message",
            required=True,
            info="直接连接 Chat Input 节点的输出端"
        )
    ]

    outputs = [
        Output(
        display_name="Profiling Result",
        name="profiling_result",
        method="build"
        )
    ]   

    def build(self) -> Data:
        input_message: Message = self.input_message  # 通过 self 访问输入

        try:
            file_path = None

            # 流派 A：从 files 属性提取
            if hasattr(input_message, 'files') and input_message.files:
                first_file = input_message.files[0]
                if isinstance(first_file, dict):
                    file_path = first_file.get('path') or first_file.get('file_path')
                else:
                    file_path = getattr(first_file, 'path', None) or getattr(first_file, 'file_path', None)

            # 流派 B：从 data 字典提取
            if not file_path and hasattr(input_message, 'data') and isinstance(input_message.data, dict):
                file_dict = input_message.data
                if 'files' in file_dict and file_dict['files']:
                    first_file = file_dict['files'][0]
                    if isinstance(first_file, dict):
                        file_path = first_file.get('path') or first_file.get('file_path')
                else:
                    file_path = file_dict.get('path') or file_dict.get('file_path') or file_dict.get('text')

            # 流派 C：兜底，从文本中提取路径
            if not file_path:
                text_content = str(getattr(input_message, 'text', input_message)).strip()
                if "/" in text_content or "\\" in text_content:
                    file_path = text_content

            if not file_path:
                return Data(text=json.dumps({"error": "未检测到文件路径，请确认已上传 CSV"}, ensure_ascii=False))

            # 加载 CSV
            df = pd.read_csv(file_path)

            # Data Profiling 逻辑（保持你原有的不变）
            def get_data_profiling(df):
                profile = {}
                total_rows = len(df)
                profile['total_rows'] = total_rows
                clean_re = re.compile(r'[$,%]')

                def clean_numeric(series):
                    if pd.api.types.is_numeric_dtype(series):
                        return series
                    try:
                        cleaned = series.astype(str).str.replace(clean_re, '', regex=True)
                        return pd.to_numeric(cleaned, errors='coerce')
                    except:
                        return pd.to_numeric(series, errors='coerce')

                fields_analysis = []
                for col in df.columns:
                    col_info = {}
                    col_info['field_name'] = col
                    col_info['data_type'] = str(df[col].dtype)
                    col_info['missing_values'] = int(df[col].isnull().sum())
                    col_info['unique_count'] = int(df[col].nunique())

                    numeric_series = clean_numeric(df[col])
                    if numeric_series.notnull().sum() / max(total_rows, 1) > 0.3:
                        col_info['is_numeric'] = True
                        valid_nums = numeric_series.dropna()
                        col_info['min'] = float(valid_nums.min()) if not valid_nums.empty else 0
                        col_info['max'] = float(valid_nums.max()) if not valid_nums.empty else 0
                        col_info['mean'] = round(float(valid_nums.mean()), 2) if not valid_nums.empty else 0
                    else:
                        col_info['is_numeric'] = False
                        col_info['sample_values'] = df[col].dropna().unique()[:5].tolist()

                    fields_analysis.append(col_info)

                profile['fields'] = fields_analysis
                sample_size = min(5, total_rows)
                profile['raw_data_samples'] = df.sample(n=sample_size).to_dict(orient='records')
                return profile

            result_profile = get_data_profiling(df)
            result_profile['file_path'] = file_path

            return Data(text=json.dumps(result_profile, ensure_ascii=False))

        except Exception as e:
            return Data(text=json.dumps({"error": f"执行失败: {str(e)}"}, ensure_ascii=False))

import importlib

from langchain_experimental.utilities import PythonREPL

from lfx.custom.custom_component.component import Component
from lfx.io import MultilineInput, Output, StrInput
from lfx.schema.data import Data


class PythonREPLComponent(Component):
    display_name = "Python Interpreter"
    description = "Run Python code with optional imports. Use print() to see the output."
    documentation: str = "https://docs.langflow.org/python-interpreter"
    icon = "square-terminal"

    inputs = [
        StrInput(
            name="global_imports",
            display_name="Global Imports",
            info="A comma-separated list of modules to import globally, e.g. 'math,numpy,pandas'.",
            value="math,pandas",
            required=True,
        ),
        MultilineInput(
            name="python_code",
            display_name="Python Code",
            info="The Python code to execute. Only modules specified in Global Imports can be used.",
            value="print('Hello, World!')",
            input_types=["Message"],
            tool_mode=True,
            required=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Results",
            name="results",
            type_=Data,
            method="run_python_repl",
        ),
    ]

    def get_globals(self, global_imports: str | list[str]) -> dict:
        """Create a globals dictionary with only the specified allowed imports."""
        global_dict = {}

        try:
            if isinstance(global_imports, str):
                modules = [module.strip() for module in global_imports.split(",")]
            elif isinstance(global_imports, list):
                modules = global_imports
            else:
                msg = "global_imports must be either a string or a list"
                raise TypeError(msg)

            for module in modules:
                try:
                    imported_module = importlib.import_module(module)
                    global_dict[imported_module.__name__] = imported_module
                except ImportError as e:
                    msg = f"Could not import module {module}: {e!s}"
                    raise ImportError(msg) from e

        except Exception as e:
            self.log(f"Error in global imports: {e!s}")
            raise
        else:
            self.log(f"Successfully imported modules: {list(global_dict.keys())}")
            return global_dict

    def run_python_repl(self) -> Data:
        try:
            globals_ = self.get_globals(self.global_imports)
            python_repl = PythonREPL(_globals=globals_)
            result = python_repl.run(self.python_code)
            result = result.strip() if result else ""

            self.log("Code execution completed successfully")
            return Data(data={"result": result})

        except ImportError as e:
            error_message = f"Import Error: {e!s}"
            self.log(error_message)
            return Data(data={"error": error_message})

        except SyntaxError as e:
            error_message = f"Syntax Error: {e!s}"
            self.log(error_message)
            return Data(data={"error": error_message})

        except (NameError, TypeError, ValueError) as e:
            error_message = f"Error during execution: {e!s}"
            self.log(error_message)
            return Data(data={"error": error_message})

    def build(self):
        return self.run_python_repl
